import { ButtonConfig } from "espd-common/button";
import { MessageConfig } from "espd-common/i18n";

export enum AlertType { success, warning, primary, danger }
export enum AlertDisplay { inline, growl }

export interface AlertButton extends Omit<ButtonConfig, 'routerPath' | 'path' | 'queryParams' | 'type'> {
	/** Dismiss alert when this action is triggered */
	closeOnClick?: boolean;
}

export class Alert {

	private static nextId = 0;

	public alertType: string;
	public id: number = Alert.nextId++;

	constructor(
		public type: AlertType,
		public message: string | MessageConfig,
		public header = '',
		public display: AlertDisplay = AlertDisplay.inline,
		public autoCloseTimeout?: number,
		public buttons?: AlertButton[]
	) {
		this.alertType = AlertType[type];
	}
}