import { animate, state, style, transition, trigger } from '@angular/animations';
import {
	Component,
	EventEmitter,
	inject,
	input,
	Input,
	OnInit,
	Output
} from '@angular/core';
import { ButtonComponent } from 'espd-common/button';
import { MessageComponent, MessageConfig, MessageService } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { AlertButton } from './alert.model';

const animationDurationMs = 300;

@Component({
	selector: 'espd-alert',
	templateUrl: 'alert.component.html',
	styleUrls: ['alert.component.scss'],
	animations: [
		trigger('openClose', [
			state('open', style({
				opacity: 1
			})),
			state('closed', style({
				opacity: 0
			})),
			transition('open => closed', [
				animate(`${animationDurationMs}ms`)
			])
		])
	],
	imports: [
		ButtonComponent,
		IconDirective,
		MessageComponent
	]
})

export class AlertComponent implements OnInit {

	private static nextId = 0;

	private messageService = inject(MessageService);

	@Input() public header?: MessageConfig;
	@Input() public message?: MessageConfig;

	/** Sets the title and screen-reader text for the close button. Default is "close". */
	closeButtonLabel = input<MessageConfig>({ key: 'common.close' });

	get closeButtonText(): string {
		return this.messageService.evaluate(this.closeButtonLabel());
	}


	/** Alert type.
	 * Provides one of four supported contextual classes:
	 * `success`, `primary`, `warning` and `danger`
	 */
	@Input() public type = 'primary';

	/** If set, displays an inline "Close" button */
	@Input() public dismissible = true;

	/** Number in milliseconds, after which alert will be closed */
	@Input() public dismissOnTimeout?: number | string;

	/** Action buttons */
	@Input() public buttons?: AlertButton[];

	/** This event fires immediately after close instance method is called,
	 * $event is an instance of Alert component.
	 */
	@Output() public readonly alertClose = new EventEmitter<AlertComponent>();

	/** This event fires when alert closed, $event is an instance of Alert component */
	@Output() public readonly alertClosed = new EventEmitter<AlertComponent>();

	/** An ID to identify this component instance. Used for generating unique IDs in the DOM */
	public id: number;

	/** Is alert visible */
	public isOpen = true;
	public isClosed = false;

	constructor() {
		this.id = AlertComponent.nextId++;
	}

	public ngOnInit(): void {
		if (this.dismissOnTimeout) {
			// if dismissOnTimeout used as attr without binding, it will be a string
			setTimeout(
				() => this.close(),
				parseInt(this.dismissOnTimeout as string, 10)
			);
		}
	}

	public clicked(button: AlertButton): void {
		if (button.closeOnClick) {
			this.close();
		}
	}

	public get isMessageString(): boolean {
		return typeof this.message === 'string';
	}

	/**
	 * Closes an alert by removing it from the DOM.
	 */
	public close(): void {
		if (!this.isOpen) {
			return;
		}

		this.alertClose.emit(this);
		this.isOpen = false;
		setTimeout(() => {
			this.isClosed = true;
			this.alertClosed.emit(this);
		}, animationDurationMs);
	}
}