import { NgClass } from '@angular/common';
import {
	ChangeDetectionStrategy,
	Component,
	input
} from '@angular/core';
import { ButtonComponent, ButtonConfig } from 'espd-common/button';
import { MessageComponent, MessageConfig } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';

@Component({
	selector: 'espd-inline-alert',
	templateUrl: 'inline-alert.component.html',
	styleUrls: ['alert.component.scss'],
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [ButtonComponent, IconDirective, MessageComponent, NgClass]
})
export class InlineAlertComponent {

	public readonly message = input<MessageConfig>();

	/** Alert type.
	 * Provides one of four supported contextual classes:
	 * `success`, `primary`, `warning` and `danger`
	 */
	public readonly type = input('primary');

	/** Is alert standalone */
	public readonly standalone = input(false);

	public readonly button = input<ButtonConfig>();

	public icons: Record<string, string> = {
		success: 'rvt-check-circle',
		primary: 'rvt-info-circle',
		warning: 'rvt-minus-circle',
		danger: 'rvt-close-circle'
	};
}