import { Component, inject } from '@angular/core';
import { AlertListService } from './alert-list.service';
import { Alert } from './alert.model';

@Component({
	selector: 'espd-alert-list',
	templateUrl: 'alert-list.component.html',
	styleUrls: ['alert-list.component.scss'],
	standalone: false
})
export class AlertListComponent {

	private alertListService = inject(AlertListService);

	public alerts = this.alertListService.alerts;
	public growls = this.alertListService.growls;

	public alertClosed(alert: Alert): void {
		this.alertListService.removeAlert(alert);
	}
}