import { inject, Injectable } from '@angular/core';
import { ApplicationConfig } from 'espd-common/config';
import { MessageConfig, MessageService } from 'espd-common/i18n';
import { BehaviorSubject, Observable } from 'rxjs';
import { Alert, AlertButton, AlertDisplay, AlertType } from './alert.model';

@Injectable()
export class AlertListService {
	private alertsSubject: BehaviorSubject<Alert[]> = new BehaviorSubject<Alert[]>([]);
	public readonly alerts: Observable<Alert[]> = this.alertsSubject.asObservable();

	private growlsSubject: BehaviorSubject<Alert[]> = new BehaviorSubject<Alert[]>([]);
	public readonly growls: Observable<Alert[]> = this.growlsSubject.asObservable();

	private messageService = inject(MessageService);
	private config = inject(ApplicationConfig);

	public addAlert(message: string | MessageConfig, type: AlertType, header?: string, display: AlertDisplay = AlertDisplay.inline, autoCloseTimeout?: number, buttons?: AlertButton[]): Alert {
		const newAlert: Alert = new Alert(type, message, header, display, autoCloseTimeout, buttons);
		this.add(newAlert);
		return newAlert;
	}

	/**
		@deprecated use addAlert with a MessageConfig parameter.
	*/
	public addInternationalizedAlert(messageKey: string, type: AlertType, display: AlertDisplay = AlertDisplay.inline, autoCloseTimeout?: number, buttons?: AlertButton[]): Alert {
		const message: string = this.messageService.get(messageKey);
		return this.addAlert(message, type, undefined, display, autoCloseTimeout, buttons);
	}

	public removeAlert(alert: Alert): void {
		if (AlertDisplay.growl === alert.display) {
			this.remove(alert, this.growlsSubject);
		} else {
			this.remove(alert, this.alertsSubject);
		}
	}

	public addSaveSuccessMessage(successMessage?: string | MessageConfig): Alert {
		return this.addAlert(successMessage ?? this.messageService.get('common.alert.saveSuccess'), AlertType.success, undefined, AlertDisplay.growl);
	}

	public addDeleteSuccessMessage(successMessage?: string | MessageConfig): Alert {
		return this.addAlert(successMessage ?? this.messageService.get('common.alert.deleteSuccess'), AlertType.success, undefined, AlertDisplay.growl);
	}

	public addErrorMessage(): Alert {
		return this.addAlert({ key: 'common.alert.error' }, AlertType.danger, undefined, AlertDisplay.growl);
	}

	public addValidationErrorMessage(): Alert {
		return this.addAlert({ key: 'common.alert.validationError' }, AlertType.danger, undefined, AlertDisplay.growl, 5);
	}

	public addPopupWarningMessage(): Alert {
		return this.addAlert({ key: 'common.alert.popupBlocked' }, AlertType.danger, undefined, AlertDisplay.growl);
	}

	private add(a: Alert) {
		if (a.type !== AlertType.danger) {
			if (!a.autoCloseTimeout && !(a.buttons?.length)) {
				a.autoCloseTimeout = this.config.alertListDefaultTimeout;
			}
		} else {
			a.autoCloseTimeout = undefined;
		}

		let subject: BehaviorSubject<Alert[]> = this.alertsSubject;
		if (a.display === AlertDisplay.growl) {
			subject = this.growlsSubject;
		}

		const currentAlerts: Alert[] = subject.getValue();
		currentAlerts.push(a);
		subject.next(currentAlerts);
	}

	private remove(alert: Alert, subject: BehaviorSubject<Alert[]>) {
		const currentAlerts: Alert[] = subject.getValue();
		const index: number = currentAlerts.indexOf(alert);

		if (index >= 0) {
			currentAlerts.splice(index, 1);
			subject.next(currentAlerts);
		}
	}
}